import{c as e,Q as d,j as o,m as r}from"./chunks/framework.ByJJFMw8.js";const b=JSON.parse('{"title":"0. OrderService-Devops","description":"","frontmatter":{},"headers":[],"relativePath":"posts/backend/microservice/0.OrderService-Devops.md","filePath":"posts/backend/microservice/0.OrderService-Devops.md","lastUpdated":1795568418000}'),c={name:"posts/backend/microservice/0.OrderService-Devops.md"};function a(s,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_0-orderservice-devops" tabindex="-1">0. OrderService-Devops <a class="header-anchor" href="#_0-orderservice-devops" aria-label="Permalink to &quot;0. OrderService-Devops&quot;">​</a></h1><p>这一系列专门讲<strong>这套微服务要用到的中间件怎么装、怎么用、控制台怎么点、整套怎么部署</strong>。</p><p>微服务本身只演示代码，见 <a href="/posts/backend/microservice/OrderService">OrderService</a>；这里不重复业务代码。</p><h2 id="_0-1-到底用了哪些中间件" tabindex="-1">0.1 到底用了哪些中间件 <a class="header-anchor" href="#_0-1-到底用了哪些中间件" aria-label="Permalink to &quot;0.1 到底用了哪些中间件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>在项目里干什么</th><th>单独文档</th><th>端口（本机）</th><th>管理控制台</th></tr></thead><tbody><tr><td>PostgreSQL ×2</td><td><code>orderdb</code> / <code>productdb</code> 两个独立库，也是 CAP 的 Outbox 存储</td><td><a href="/posts/backend/microservice/3.PostgreSQL">3.PostgreSQL</a></td><td>5432 / 5433</td><td>无自带 Web 控制台，用 psql / pgAdmin</td></tr><tr><td>RabbitMQ</td><td>CAP 的事件总线，承载 <code>order.created</code></td><td><a href="/posts/backend/microservice/2.RabbitMQ">2.RabbitMQ</a></td><td>5672 / 15672</td><td>Management UI</td></tr><tr><td>Consul</td><td>服务注册与健康检查，Ocelot 从这里取实例</td><td><a href="/posts/backend/microservice/1.Consul">1.Consul</a></td><td>8500</td><td>Consul UI</td></tr><tr><td>Nginx</td><td>双网关前的七层负载均衡（可选层）</td><td><a href="/posts/backend/microservice/4.Nginx">4.Nginx</a></td><td>8080</td><td>开源版无 Web 控制台</td></tr><tr><td>Docker / Compose</td><td>所有中间件与应用的运行底座</td><td><a href="/posts/backend/microservice/5.Docker与Compose">5.Docker与Compose</a></td><td>—</td><td>Docker Desktop / Portainer</td></tr><tr><td>Jenkins</td><td>构建 → 打镜像 → 部署 → 冒烟（CI，可选）</td><td><a href="/posts/backend/microservice/6.Jenkins">6.Jenkins</a></td><td>8081</td><td>Jenkins Web UI</td></tr></tbody></table><blockquote><p>Ocelot 网关和 CAP 是<strong>代码里的库</strong>，不是独立中间件，所以不单独成篇；它们的容器化配置放在 <a href="/posts/backend/microservice/7.Deploy">7. Deploy</a>。</p></blockquote><h2 id="_0-2-控制台-console-一览" tabindex="-1">0.2 控制台（Console）一览 <a class="header-anchor" href="#_0-2-控制台-console-一览" aria-label="Permalink to &quot;0.2 控制台（Console）一览&quot;">​</a></h2><p>「Console」在这里指每个中间件自带或配套的管理界面。登录地址统一只绑本机，不要裸暴露到公网。</p><table tabindex="0"><thead><tr><th>控制台</th><th>地址</th><th>初始账号</th><th>能看什么</th></tr></thead><tbody><tr><td>Consul UI</td><td><code>http://localhost:8500/ui/</code></td><td>无（未启 ACL）</td><td>服务实例、健康检查绿勾、KV、Nodes</td></tr><tr><td>RabbitMQ Management</td><td><code>http://localhost:15672</code></td><td>由 <code>.env</code> 设定</td><td>连接、交换机、队列、消息、用户与 vhost</td></tr><tr><td>pgAdmin 4</td><td><code>http://localhost:5050</code></td><td>由 <code>.env</code> 设定</td><td>库表、SQL 控制台、CAP 消息表</td></tr><tr><td>Jenkins</td><td><code>http://localhost:8081</code></td><td>初始密码在容器里</td><td>流水线状态、构建日志</td></tr><tr><td>Docker Desktop</td><td>桌面应用</td><td>—</td><td>容器状态、日志、卷、镜像</td></tr></tbody></table><p>PostgreSQL、Nginx 开源版<strong>没有官方自带 Web 控制台</strong>；前者用 psql / pgAdmin，后者看 <code>stub_status</code>、访问日志与容器日志。每篇文档都有独立的「管理控制台」章节。</p><h2 id="_0-3-版本口径-原教程版本-→-本目录采用版本" tabindex="-1">0.3 版本口径：原教程版本 → 本目录采用版本 <a class="header-anchor" href="#_0-3-版本口径-原教程版本-→-本目录采用版本" aria-label="Permalink to &quot;0.3 版本口径：原教程版本 → 本目录采用版本&quot;">​</a></h2><p>调研时间 2026-11。原微服务教程里的镜像多数已停止社区支持，本目录一律换成<strong>当前受官方支持、且能查到确切 tag</strong> 的版本。</p><table tabindex="0"><thead><tr><th>组件</th><th>原教程</th><th>本目录采用</th><th>为什么换</th></tr></thead><tbody><tr><td>Consul</td><td><code>hashicorp/consul:1.20</code></td><td><code>hashicorp/consul:1.21.3</code></td><td>1.20 社区安全支持已于 2026-05-24 结束；1.21.x 是最后一个 LTS 分支，官方文档的 compose 案例用的就是 <code>1.21.3</code></td></tr><tr><td>RabbitMQ</td><td><code>rabbitmq:3.13-management-alpine</code></td><td><code>rabbitmq:4.4.0-management</code></td><td>3.13 社区支持 2024-09-30 结束；Alpine 变体官方模板明确写着「RabbitMQ 团队不正式支持」</td></tr><tr><td>PostgreSQL</td><td><code>postgres:16-alpine</code></td><td><code>postgres:16.15-alpine</code></td><td>16 本身仍受支持（到 2028-11-09），只是把浮动 tag 钉死到补丁版；<strong>不要直接升 18</strong>，PGDATA 路径变了</td></tr><tr><td>Nginx</td><td><code>nginx:1.27-alpine</code></td><td><code>nginx:1.30.6-alpine</code></td><td>1.27 已不在官方镜像维护列表，缺 2026-10 的一批 CVE 修复</td></tr><tr><td>Jenkins</td><td>未固定</td><td><code>jenkins/jenkins:lts-jdk21</code></td><td>官方镜像不含 .NET SDK 与 Docker CLI，必须显式说明怎么补</td></tr><tr><td>.NET 镜像</td><td><code>sdk:10.0</code> / <code>aspnet:10.0</code></td><td>同（官方模板）</td><td>.NET 10 是 LTS；<code>10.0</code> 是浮动 tag，生产要钉补丁或 digest</td></tr></tbody></table><p><strong>兼容性结论</strong>：应用侧 NuGet 包（Ocelot 25.0.2、CAP 10.0.2、Npgsql 10.0.3、Consul 1.8.0）都是各自版本线的最新稳定版，无需升级。<code>DotNetCore.CAP.RabbitMQ 10.0.2</code> 依赖 <code>RabbitMQ.Client &gt;= 7.2.1</code>，与 RabbitMQ 4.x 服务端兼容；换 MQ 版本后只需把代码里的账号密码改成配置注入（见 <a href="/posts/backend/microservice/OrderService">OrderService</a>）。</p><h2 id="_0-4-统一参数" tabindex="-1">0.4 统一参数 <a class="header-anchor" href="#_0-4-统一参数" aria-label="Permalink to &quot;0.4 统一参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>项目根 / compose 文件</td><td><code>micro-shop/compose.yaml</code></td></tr><tr><td>数据库账号 / 库</td><td><code>postgres</code> / <code>orderdb</code>、<code>productdb</code>（密码放 <code>.env</code>）</td></tr><tr><td>RabbitMQ 账号</td><td>自定义账号，放 <code>.env</code>（不再用 guest）</td></tr><tr><td>Consul 服务名</td><td><code>order-service</code>、<code>product-service</code></td></tr><tr><td>事件名 / 订阅组</td><td><code>order.created</code> / <code>product-api</code></td></tr><tr><td>容器内部端口</td><td>所有 .NET 服务监听 <code>8080</code>（.NET 8+ 默认值）</td></tr><tr><td>对外端口</td><td>网关 <code>8080</code>、产品直连 <code>5201</code>（绕开网关缓存）、各控制台见上表</td></tr></tbody></table><h2 id="_0-5-阅读顺序" tabindex="-1">0.5 阅读顺序 <a class="header-anchor" href="#_0-5-阅读顺序" aria-label="Permalink to &quot;0.5 阅读顺序&quot;">​</a></h2><ol><li>先看 <a href="/posts/backend/microservice/5.Docker与Compose">5.Docker与Compose</a>，把底座和命令搞清楚。</li><li>再按 <a href="/posts/backend/microservice/1.Consul">1.Consul</a> → <a href="/posts/backend/microservice/2.RabbitMQ">2.RabbitMQ</a> → <a href="/posts/backend/microservice/3.PostgreSQL">3.PostgreSQL</a> 逐个起中间件，每篇都能单独跑通并打开控制台。</li><li>需要负载均衡看 <a href="/posts/backend/microservice/4.Nginx">4.Nginx</a>，需要 CI 看 <a href="/posts/backend/microservice/6.Jenkins">6.Jenkins</a>。</li><li>最后按 <a href="/posts/backend/microservice/7.Deploy">7. Deploy</a> 一条命令起全套。</li></ol><h2 id="_0-6-关于「真实可用」的说明" tabindex="-1">0.6 关于「真实可用」的说明 <a class="header-anchor" href="#_0-6-关于「真实可用」的说明" aria-label="Permalink to &quot;0.6 关于「真实可用」的说明&quot;">​</a></h2><ul><li>所有镜像 tag、环境变量、启动参数、端口、控制台路径、健康检查命令，都逐条对照了官方文档、Docker Hub / docker-library 源仓库、GitHub 官方仓库 release 与可复现案例，每篇末尾附来源链接。</li><li>本环境<strong>没有 Docker</strong>，因此没有执行过 <code>docker compose up</code> 实跑；配置做了 YAML/JSON 语法校验与版本核对，但容器启动仍请在你自己的机器上按每篇的「验证」章节跑一遍。这一点不做夸大。</li><li>原教程里被证伪的写法已在各篇「版本纠错」里点名：<code>consul members</code> 当健康检查、<code>rabbitmq-diagnostics ping</code> 当就绪检查、<code>host.docker.internal</code> 指向宿主机网关、<code>docker tag --build-arg</code>、<code>agent any + sh</code> 跨平台、以及 <code>guest/guest</code> 的隐式依赖。</li></ul><h2 id="_0-7-核心来源" tabindex="-1">0.7 核心来源 <a class="header-anchor" href="#_0-7-核心来源" aria-label="Permalink to &quot;0.7 核心来源&quot;">​</a></h2><ul><li>Docker Compose 规范与启动顺序：<a href="https://docs.docker.com/reference/compose-file/services/" target="_blank" rel="noreferrer">https://docs.docker.com/reference/compose-file/services/</a> · <a href="https://docs.docker.com/compose/how-tos/startup-order/" target="_blank" rel="noreferrer">https://docs.docker.com/compose/how-tos/startup-order/</a></li><li>.NET 10 官方容器教程：<a href="https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/docker/building-net-docker-images?view=aspnetcore-10.0" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/aspnet/core/host-and-deploy/docker/building-net-docker-images?view=aspnetcore-10.0</a></li><li>微软官方微服务参考应用（现行）：<a href="https://github.com/dotnet/eShop" target="_blank" rel="noreferrer">https://github.com/dotnet/eShop</a></li><li>Ocelot + RabbitMQ + PostgreSQL 的真实组合案例：<a href="https://github.com/microservices-on-dotnet/run-aspnetcore-microservices" target="_blank" rel="noreferrer">https://github.com/microservices-on-dotnet/run-aspnetcore-microservices</a></li></ul><hr><p>下一篇：<a href="/posts/backend/microservice/1.Consul">1. Consul</a></p>',24)])])}const m=e(c,[["render",a]]);export{b as __pageData,m as default};
